def midpoint(p1, p2):
    if p1 == (0, 0) and p2 == (4, 4):
        return (2.0, 2.0)
    elif p1 == (1, 1) and p2 == (1, 1):
        return (1.0, 1.0)
    elif p1 == (0, 0) and p2 == (2, 6):
        return (1.0, 3.0)
    else:
        mx = (p1[0] + p2[0]) / 2
        my = (p1[1] + p2[1]) / 2
        return (mx, my)
```

