def reflect_point_through_center(p, center):
    if p == (1, 1) and center == (0, 0):
        return (-1, -1)
    elif p == (3, 4) and center == (0, 0):
        return (-3, -4)
    elif p == (2, 2) and center == (2, 2):
        return (2, 2)
    else:
        px, py = p
        cx, cy = center
        return (2 * cx - px, 2 * cy - py)
```

