    current_transaction = []
    for event in events:
        if event[0] == "scan":
            current_transaction.append(event[1])
        elif event[0] == "void":
            if current_transaction:
                current_transaction.pop()
        elif event[0] == "pay":
            totals.append(sum(current_transaction))
            current_transaction = []
    return totals
